function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }
const t = $('When Executed by Another Workflow').first().json;
const modeloName = String(t.modelo || '').trim();
const enganche   = Number(t.enganche) || 0;
let   plazo      = Number(t.plazo_meses) || 0;

// ---- Financiera activa ----
let fin = {}; let finId = null;
try { const r = $('Airtable · Get Financiera').first().json; finId = r && r.id; fin = F(r); } catch(e) {}
const tasaPct   = Number(fin.tasa_anual_pct);
const tasaAnual = (isFinite(tasaPct) && tasaPct > 0) ? tasaPct/100 : 0.36; // fallback EJEMPLO
const plazos    = String(fin.plazos_disponibles || '12,24,36').split(',').map(s=>parseInt(s.trim(),10)).filter(Boolean);
const engMinPct = Number(fin.enganche_minimo_pct) || 20;
const link      = fin.link_base || '';
const finNombre = fin.nombre || 'la financiera';

// ---- Precio del modelo (fuente de verdad: tabla Modelos) ----
// NOTA: se usa el precio de LISTA. El bono de promo es de CONTADO, no aplica a crédito.
let mod = {};
try { mod = F($('Airtable · Get Modelo').first().json); } catch(e) {}
const precio = Number(mod.precio) || 0;

const fmt = (n) => '$' + Math.round(Number(n)).toLocaleString('en-US');

// ---- Validaciones ----
if (!modeloName || !precio) {
  return [{ json: { ok:false, motivo:'sin_precio',
    mensaje_agente: 'No pude tomar el precio de ese modelo del catálogo. Pregúntale al cliente qué modelo exacto le interesa y vuelve a intentar; si el modelo no está en el catálogo, ofrécele pasarlo con un asesor.' }}];
}

// Plazo: si no viene o no está en los que maneja la financiera, usa el más cercano disponible.
if (!plazo) plazo = plazos[plazos.length-1] || 24;
if (plazos.length && !plazos.includes(plazo)) {
  plazo = plazos.reduce((a,b) => Math.abs(b-plazo) < Math.abs(a-plazo) ? b : a, plazos[0]);
}

const engMin = Math.round(precio * engMinPct / 100);
const engancheUsado = Math.max(enganche, 0);
const engancheInsuficiente = engancheUsado < engMin;

const monto = Math.max(0, precio - engancheUsado);
const i = tasaAnual / 12;
let mensualidad = (i === 0) ? (plazo ? monto/plazo : 0)
                            : monto * (i * Math.pow(1+i, plazo)) / (Math.pow(1+i, plazo) - 1);
mensualidad = Math.round(mensualidad);
const totalPagar = Math.round(mensualidad * plazo + engancheUsado);

let mensaje_agente =
  `PRECOTIZACIÓN ESTIMADA (compártela con el cliente en tus palabras, tono natural):\n` +
  `• Modelo: ${modeloName} — precio de lista ${fmt(precio)}\n` +
  `• Enganche considerado: ${fmt(engancheUsado)}\n` +
  `• Plazo: ${plazo} meses\n` +
  `• Mensualidad estimada: ${fmt(mensualidad)}\n` +
  `• Total estimado a pagar: ${fmt(totalPagar)}\n\n` +
  `REGLAS AL DARLA:\n` +
  `- Dile SIEMPRE que es una PRECOTIZACIÓN estimada y que el monto final lo define ${finNombre} al revisar su solicitud.\n` +
  `- NO prometas aprobación.\n`;

if (engancheInsuficiente) {
  mensaje_agente += `- OJO: el enganche que dio (${fmt(engancheUsado)}) está por debajo del mínimo sugerido (${fmt(engMin)}, ${engMinPct}%). Coméntaselo con tacto y anímalo a subirlo, pero igual puede intentar la solicitud.\n`;
}
if (plazos.length > 1) {
  mensaje_agente += `- Plazos disponibles: ${plazos.join(', ')} meses. Si quiere ver otro plazo, vuelve a llamar la tool con ese plazo.\n`;
}

if (link) {
  mensaje_agente += `\nSIGUIENTE PASO — MÁNDALE ESTE LINK TAL CUAL (no lo modifiques):\n${link}\n` +
    `Explícale que ahí llena sus datos con ${finNombre} y que en cuanto tengan respuesta se la avisas por aquí mismo.`;
} else {
  mensaje_agente += `\nNo hay link de solicitud configurado. Ofrécele pasarlo con un asesor para continuar el trámite.`;
}

return [{ json: {
  ok: true,
  user_id_canal: t.user_id_canal,
  modelo: modeloName, precio,
  enganche: engancheUsado, enganche_minimo: engMin, enganche_insuficiente: engancheInsuficiente,
  plazo_meses: plazo, plazos_disponibles: plazos,
  tasa_anual: tasaAnual, mensualidad_estimada: mensualidad, total_a_pagar: totalPagar,
  financiera_nombre: finNombre, financiera_rec: finId, link,
  mensaje_agente
}}];

function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }

// ── Normalizador de nombres de catálogo ────────────────────────────────────
// El LLM nunca va a reproducir el nombre exacto del CRM. Esta función deja
// "Pulsar NS200", "pulsar ns-200" y "Bajaj  Pulsar NS 200" en la misma forma
// canónica: "pulsar ns 200". Clave: separa letras de números, porque el CRM
// escribe "NS 200" y el agente casi siempre manda "NS200".
function norm(s){
  return String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // acentos
    .replace(/[^a-z0-9]+/g, ' ')                        // guiones, +, puntos…
    .replace(/([a-z])(\d)/g, '$1 $2')                   // ns200  -> ns 200
    .replace(/(\d)([a-z])/g, '$1 $2')                   // 200fi  -> 200 fi
    .replace(/\bbajaj\b/g, ' ')                         // la marca no distingue
    .replace(/\s+/g, ' ')
    .trim();
}
const toks = (s) => norm(s).split(' ').filter(Boolean);

// Busca `query` dentro de `lista` (cada item con .id y campo `campo`).
// Devuelve { hit, candidatos, via }. Cascada de menos a más permisivo, y
// si al final hay empate NO adivina: devuelve los candidatos para preguntar.
function buscar(lista, query, campo){
  const q = norm(query);
  const qt = toks(query);
  if (!q || !lista.length) return { hit:null, candidatos:[], via:'sin_query' };

  const conNorm = lista.map(x => ({ ...x, _n: norm(x[campo]), _t: toks(x[campo]) }));

  // 1. Igual ya normalizado — "Pulsar NS200" == "Pulsar NS 200"
  let c = conNorm.filter(x => x._n === q);
  if (c.length === 1) return { hit:c[0], candidatos:c, via:'exacto' };

  // 2. Todos los tokens de la búsqueda están en el candidato.
  //    Gana el que tenga MENOS palabras de más: entre "Pulsar NS 200" y
  //    "Pulsar NS 200 FI ABS", para "NS200" gana el primero.
  c = conNorm.filter(x => qt.every(t => x._t.includes(t)));
  if (c.length) {
    c.sort((a,b) => (a._t.length - qt.length) - (b._t.length - qt.length));
    const mejor = a => a._t.length - qt.length;
    const empatados = c.filter(x => mejor(x) === mejor(c[0]));
    if (empatados.length === 1) return { hit:c[0], candidatos:c, via:'contiene' };
    return { hit:null, candidatos:empatados, via:'ambiguo' };
  }

  // 3. Al revés: el cliente escribió de más ("Pulsar NS200 modelo 2026").
  c = conNorm.filter(x => x._t.length && x._t.every(t => qt.includes(t)));
  if (c.length === 1) return { hit:c[0], candidatos:c, via:'contenido_en_query' };
  if (c.length > 1)   return { hit:null, candidatos:c, via:'ambiguo' };

  // 4. Último intento: mismo número de cilindrada + primera palabra.
  const num = qt.find(t => /^\d+$/.test(t));
  if (num) {
    c = conNorm.filter(x => x._t.includes(num) && x._t[0] === qt[0]);
    if (c.length === 1) return { hit:c[0], candidatos:c, via:'cilindrada' };
    if (c.length > 1)   return { hit:null, candidatos:c, via:'ambiguo' };
  }

  return { hit:null, candidatos:[], via:'no_encontrado' };
}

const t = $('When Executed by Another Workflow').first().json;
const modeloName     = String(t.modelo || '').trim();
const enganche       = Number(t.enganche) || 0;
let   plazo          = Number(t.plazo_meses) || 0;
const financieraName = String(t.financiera || '').trim();

// ---- Validar que llegue financiera ----
if (!financieraName) {
  return [{ json: { ok:false, motivo:'sin_financiera',
    mensaje_agente: 'ANTES de calcular el aproximado necesitas que el cliente ELIJA una financiera. Preséntale las financieras disponibles (vienen en el contexto en financieras_disponibles), deja que el cliente escoja, guarda su elección con actualizar_lead(financiera_elegida:"NOMBRE") y luego vuelve a llamar esta tool pasando la financiera elegida.' }}];
}

// ---- Financiera: match tolerante sobre las activas ----
let financieras = [];
try {
  financieras = $('Airtable · Get Financiera1').all().map(i=>i.json).filter(r=>r&&r.id)
    .map(r => ({ id:r.id, ...F(r) }))
    .filter(f => f.activa !== false);
} catch(e) {}

const rFin = buscar(financieras, financieraName, 'nombre');
let fin = rFin.hit || null;
// Segundo intento con el nombre corto, por si el agente usó el alias.
if (!fin && rFin.via === 'no_encontrado') {
  const r2 = buscar(financieras, financieraName, 'nombre_corto');
  if (r2.hit) fin = r2.hit;
}

if (!fin) {
  const nombres = financieras.map(f => f.nombre).filter(Boolean).join(', ');
  return [{ json: { ok:false, motivo:'financiera_no_encontrada',
    mensaje_agente: `No encontré la financiera "${financieraName}" activa en el catálogo. Las disponibles son: ${nombres || 'ninguna'}. Presenta al cliente SOLO ésas y deja que elija una.` }}];
}

const finId     = fin.id;
const tasaPct   = Number(fin.tasa_anual_pct);
const tasaAnual = (isFinite(tasaPct) && tasaPct > 0) ? tasaPct/100 : 0.36;
const plazosStr = String(fin.plazos_valores || fin.plazos_disponibles || '12,24,36');
const plazos    = plazosStr.split(',').map(s=>parseInt(String(s).trim(),10)).filter(Boolean);
const engMinPct = Number(fin.enganche_minimo_pct) || 10;
const link      = fin.link_base || '';
const finNombre = fin.nombre_corto || fin.nombre || financieraName;

// ---- Modelo: match tolerante sobre el catálogo activo ----
let modelos = [];
try {
  modelos = $('Airtable · Get Modelo1').all().map(i=>i.json).filter(r=>r&&r.id)
    .map(r => ({ id:r.id, ...F(r) }))
    .filter(m => m.activo !== false);
} catch(e) {}

const rMod = buscar(modelos, modeloName, 'nombre');

// Si hay empate real, NO adivinamos: que el cliente decida cuál.
if (!rMod.hit && rMod.via === 'ambiguo') {
  const ops = rMod.candidatos.map(m => m.nombre).filter(Boolean);
  return [{ json: { ok:false, motivo:'modelo_ambiguo', candidatos: ops,
    mensaje_agente: `Hay varias versiones que coinciden con "${modeloName}": ${ops.join(', ')}. Pregúntale al cliente cuál de ésas quiere (menciónaselas tal cual) y vuelve a llamar la tool con el nombre completo.` }}];
}

const mod    = rMod.hit || {};
const precio = Number(mod.precio) || 0;
const modeloReal = mod.nombre || modeloName;

const fmt = (n) => '$' + Math.round(Number(n)).toLocaleString('en-US');

if (!modeloName || !precio) {
  const ops = modelos.map(m => m.nombre).filter(Boolean).slice(0, 12).join(', ');
  return [{ json: { ok:false, motivo:'sin_precio', match_via: rMod.via,
    mensaje_agente: `No encontré "${modeloName}" con precio en el catálogo. Los modelos que sí tenemos son: ${ops}. Confirma con el cliente cuál le interesa (usa uno de esos nombres) y vuelve a intentar; si de plano no está, ofrécele pasarlo con un asesor.` }}];
}

// Plazo: si no viene o no está en los que maneja la financiera, usa el más cercano
if (!plazo) plazo = plazos[plazos.length-1] || 24;
if (plazos.length && !plazos.includes(plazo)) {
  plazo = plazos.reduce((a,b) => Math.abs(b-plazo) < Math.abs(a-plazo) ? b : a, plazos[0]);
}

const engMin = Math.round(precio * engMinPct / 100);
const engancheUsado = Math.max(enganche, 0);
const engancheInsuficiente = engancheUsado < engMin;

const monto = Math.max(0, precio - engancheUsado);
const i = tasaAnual / 12;
let mensualidad = (i === 0) ? (plazo ? monto/plazo : 0)
                            : monto * (i * Math.pow(1+i, plazo)) / (Math.pow(1+i, plazo) - 1);
mensualidad = Math.round(mensualidad);
const totalPagar = Math.round(mensualidad * plazo + engancheUsado);

let mensaje_agente =
  `CÁLCULO APROXIMADO con ${finNombre} (compártelo con el cliente en tus palabras, tono natural):\n` +
  `• Modelo: ${modeloReal} — precio de lista ${fmt(precio)}\n` +
  `• Enganche considerado: ${fmt(engancheUsado)}\n` +
  `• Plazo: ${plazo} meses\n` +
  `• Mensualidad estimada: ${fmt(mensualidad)}\n` +
  `• Total estimado a pagar: ${fmt(totalPagar)}\n\n` +
  `REGLAS AL DARLO:\n` +
  `- Usa las palabras "APROXIMADO" o "ESTIMADO" — NUNCA "precotización".\n` +
  `- Dile SIEMPRE que es un cálculo aproximado y que el monto final lo define ${finNombre} al revisar su solicitud.\n` +
  `- NO prometas aprobación.\n`;

// Si el nombre del CRM no es el que dijo el cliente, que el agente use el bueno.
if (norm(modeloReal) !== norm(modeloName)) {
  mensaje_agente += `- El nombre exacto del modelo en catálogo es "${modeloReal}" (el cliente dijo "${modeloName}"). Refiérete a él como "${modeloReal}".\n`;
}
if (engancheInsuficiente) {
  mensaje_agente += `- OJO: el enganche que dio (${fmt(engancheUsado)}) está por debajo del mínimo sugerido (${fmt(engMin)}, ${engMinPct}%). Coméntaselo con tacto y anímalo a subirlo, pero igual puede intentar la solicitud.\n`;
}
if (plazos.length > 1) {
  mensaje_agente += `- Plazos disponibles con ${finNombre}: ${plazos.join(', ')} meses. Si quiere ver otro plazo, vuelve a llamar la tool con ese plazo.\n`;
}

if (link) {
  mensaje_agente += `\nSIGUIENTE PASO — MÁNDALE ESTE LINK TAL CUAL (no lo modifiques):\n${link}\n` +
    `Explícale que ahí llena sus datos con ${finNombre} y que en cuanto tengan respuesta se la avisas por aquí mismo.`;
} else {
  mensaje_agente += `\nNo hay link de solicitud configurado para ${finNombre}. Ofrécele pasarlo con un asesor para continuar el trámite.`;
}

return [{ json: {
  ok: true,
  user_id_canal: t.user_id_canal,
  modelo: modeloReal, modelo_pedido: modeloName, match_via: rMod.via, precio,
  enganche: engancheUsado, enganche_minimo: engMin, enganche_insuficiente: engancheInsuficiente,
  plazo_meses: plazo, plazos_disponibles: plazos,
  tasa_anual: tasaAnual, mensualidad_estimada: mensualidad, total_a_pagar: totalPagar,
  financiera_nombre: finNombre, financiera_rec: finId, link,
  mensaje_agente
}}];
